import { randomUUID } from "node:crypto";

const ENDPOINT = process.env.WIMT_ENDPOINT || "https://pv-prod.whereismytrain.in/cache/live_status";
const APP_VERSION = process.env.WIMT_APP_VERSION || "7.1.5.963234518";
const WIMT_USER = process.env.WIMT_USER || "a3862ee363ec47ab945ac77675abdfac";
const TIMEOUT_MS = 20_000;

function adler32Utf8(value) {
  const bytes = new TextEncoder().encode(value);
  let a = 1;
  let b = 0;
  for (const byte of bytes) {
    a = (a + byte) % 65521;
    b = (b + a) % 65521;
  }
  return String(((b * 65536) + a) >>> 0);
}

function fail(message, status = 400) {
  return Response.json({ success: false, error: message }, { status });
}

export async function GET(request) {
  const query = new URL(request.url).searchParams;
  const trainNo = query.get("trainNo")?.trim();
  const date = query.get("date")?.trim();
  const from = query.get("from")?.trim().toUpperCase();
  const to = query.get("to")?.trim().toUpperCase();
  const fromDay = query.get("fromDay")?.trim() || "1";

  if (!/^\d{5}$/.test(trainNo || "")) return fail("trainNo must be exactly 5 digits");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date || "")) return fail("date must be YYYY-MM-DD");
  if (!from || !to) return fail("from and to station codes are required");
  if (!/^\d+$/.test(fromDay)) return fail("fromDay must be numeric");

  const qid = randomUUID().replaceAll("-", "");
  const dateWire = `${date.slice(8, 10)}-${date.slice(5, 7)}-${date.slice(0, 4)}`;
  const widInput = WIMT_USER + APP_VERSION + qid + trainNo + from + to + dateWire + fromDay;
  const params = new URLSearchParams({
    user: WIMT_USER,
    appVersion: APP_VERSION,
    sb_version: "0",
    lang: "en",
    qid,
    train_no: trainNo,
    from,
    to,
    date: dateWire,
    from_day: fromDay,
    hard_refresh: "1",
    wid: adler32Utf8(widInput),
  });

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), TIMEOUT_MS);

  try {
    const upstream = await fetch(`${ENDPOINT}?${params}`, {
      headers: {
        Accept: "application/json",
        "Cache-Control": "no-cache, no-store",
        Pragma: "no-cache",
      },
      signal: controller.signal,
    });
    const body = await upstream.text();
    if (!upstream.ok) return new Response(body, { status: upstream.status, headers: { "content-type": "application/json" } });
    try { JSON.parse(body); } catch { return fail("WIMT returned invalid JSON", 502); }
    return new Response(body, {
      status: 200,
      headers: {
        "content-type": "application/json; charset=utf-8",
        "cache-control": "no-store",
      },
    });
  } catch (error) {
    return fail(error?.name === "AbortError" ? "WIMT request timed out" : "WIMT request failed", 502);
  } finally {
    clearTimeout(timeout);
  }
}
